CREATE TRIGGER RefCusTariffUOM_Combined
	ON RefCusTariffUOM
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZZ8_DataSetPK = COALESCE(inserted.ZZ8_ZZ1_Tariff, ZZW_ZZ1_Tariff),
		ZZ8_DataSetCode = CASE WHEN inserted.ZZ8_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' ELSE CASE WHEN ZZW_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' END END 
		FROM RefCusTariffUOM t
		JOIN inserted ON t.ZZ8_PK = inserted.ZZ8_PK
		LEFT JOIN RefCusTariffNationalCode ON inserted.ZZ8_ZZW_TariffNationalCode = ZZW_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZZ8_DataSetPK, t.ZZ8_DataSetCode
	FROM RefCusTariffUOM t
	JOIN inserted ON t.ZZ8_PK = inserted.ZZ8_PK
	UNION
	SELECT ZZ8_DataSetPK, ZZ8_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

